function test_handle_http_status_code() {
    $exchange = new \ccxt\async\Exchange(array(
        'id' => 'sampleexchange',
    ));
    // every status of the default httpExceptions table must throw — one status
    // per distinct error class of the table.
    //
    // The blocks below are deliberately written out one status at a time with
    // integer literals instead of looping over a list of codes:
    //   - the C# and Java bases declare `handleHttpStatusCode (int code, ...)`,
    //     so an element read out of an untyped list does not compile there;
    //   - only *that* a status throws is asserted, never which class, because
    //     `error instanceof <Class>` inside a transpiled catch does not survive
    //     the Go port (the recover handler compares the panic payload's type
    //     against the constructor). The status → class mapping is pinned by
    //     ts/src/test/base/errors/** instead — do not weaken this list by adding
    //     statuses that are absent from httpExceptions.
    $caught = false;
    try {
        $exchange->handle_http_status_code(429, 'reason', 'url', 'GET', 'body');
    } catch(\Throwable $error) {
        $caught = true;
    }
    assert($caught, 'status 429 should have thrown');
    $caught = false;
    try {
        $exchange->handle_http_status_code(418, 'reason', 'url', 'GET', 'body');
    } catch(\Throwable $error) {
        $caught = true;
    }
    assert($caught, 'status 418 should have thrown');
    $caught = false;
    try {
        $exchange->handle_http_status_code(401, 'reason', 'url', 'GET', 'body');
    } catch(\Throwable $error) {
        $caught = true;
    }
    assert($caught, 'status 401 should have thrown');
    $caught = false;
    try {
        $exchange->handle_http_status_code(408, 'reason', 'url', 'GET', 'body');
    } catch(\Throwable $error) {
        $caught = true;
    }
    assert($caught, 'status 408 should have thrown');
    $caught = false;
    try {
        $exchange->handle_http_status_code(500, 'reason', 'url', 'GET', 'body');
    } catch(\Throwable $error) {
        $caught = true;
    }
    assert($caught, 'status 500 should have thrown');
    $caught = false;
    try {
        $exchange->handle_http_status_code(422, 'reason', 'url', 'GET', 'body');
    } catch(\Throwable $error) {
        $caught = true;
    }
    assert($caught, 'status 422 should have thrown');
    // statuses missing from the table must not throw — derived handleErrors
    // implementations rely on exactly that swallow when they guard with
    // a httpExceptions lookup before deferring to the status handler
    $exchange->handle_http_status_code(402, 'reason', 'url', 'GET', 'body');
    $exchange->handle_http_status_code(406, 'reason', 'url', 'GET', 'body');
    $exchange->handle_http_status_code(412, 'reason', 'url', 'GET', 'body');
    $exchange->handle_http_status_code(413, 'reason', 'url', 'GET', 'body');
    $exchange->handle_http_status_code(505, 'reason', 'url', 'GET', 'body');
    $exchange->handle_http_status_code(524, 'reason', 'url', 'GET', 'body');
    // success statuses never throw
    $exchange->handle_http_status_code(200, 'OK', 'url', 'GET', 'body');
    $exchange->handle_http_status_code(201, 'Created', 'url', 'GET', 'body');
    // dispatch composition: the base handleErrors stub returns undefined, so an
    // error envelope on an uncovered status passes both steps without a throw —
    // a derived handleErrors that wants to surface it must throw on its own
    $skip = $exchange->handle_errors(406, 'Not Acceptable', 'url', 'GET', array(), '{"success":false}', array(
        'success' => false,
    ), array(), '');
    assert($skip === null, 'the base handleErrors stub should return undefined');
    $exchange->handle_http_status_code(406, 'Not Acceptable', 'url', 'GET', '{"success":false}');
}
